syntax.pt:
switch (valor)
{
    case x:
        ...
        break;
    default:
        ...
        break;
}

if (condição) { ... } else { ... }

syntax.en:
switch (value)
{
    case x:
        ...
        break;
    default:
        ...
        break;
}

if (condition) { ... } else { ... }

example:
string weather = "rain";
string gear;
switch (weather)
{
    case "rain":
        gear = "cloak";
        break;
    case "snow":
        gear = "boots";
        break;
    default:
        gear = "hat";
        break;
}
